start:
set -euo pipefail
export SUPABASE_TELEMETRY_DISABLED=1
export SUPABASE_EXPERIMENTAL_STACK=1
[ ! -d '/agent/repos/calendar-themes' ] || cd '/agent/repos/calendar-themes' || exit $?
supabase --workdir /opt/caltheme-supabase start --runtime native --eager --exclude studio,mail,analytics,realtime,storage,functions,pooler | node -e '
let s="";
process.stdin.on("data", d => { s += d; });
process.stdin.on("end", () => {
  const marker = "{\"id\"";
  const i = s.indexOf(marker);
  process.stdout.write(i >= 0 ? s.slice(0, i) : s);
  if (i < 0) return;
  try {
    const parsed = JSON.parse(s.slice(i));
    console.log(JSON.stringify({ runtime: parsed.runtime || "", message: parsed.message || "ready" }));
  } catch (err) {
    console.log("stack start returned");
  }
});
'
psql_bin=$(find "$HOME/.supabase/cache/stack/slim-services/postgres" -type f -name psql -print -quit)
if [ ! -x "$psql_bin" ]; then
  echo "local psql was not installed" >&2
  exit 1
fi
eval "$(supabase --workdir /opt/caltheme-supabase status --output-format json | node -e '
let s="";
process.stdin.on("data", d => { s += d; });
process.stdin.on("end", () => {
  const env = (JSON.parse(s).env) || {};
  if (!env.DB_URL || !env.API_URL || !env.SERVICE_ROLE_KEY) {
    console.error("status JSON missing local connection fields");
    process.exit(1);
  }
  const out = (k, v) => process.stdout.write("export " + k + "=" + JSON.stringify(v) + "\n");
  out("DB_URL", env.DB_URL);
  out("SUPABASE_URL", env.API_URL);
  out("SUPABASE_SERVICE_ROLE_KEY", env.SERVICE_ROLE_KEY);
});
')"
case "$SUPABASE_URL" in
  http://127.0.0.1:*|http://localhost:*) ;;
  *) echo "refusing non-local SUPABASE_URL" >&2; exit 1 ;;
esac
"$psql_bin" "$DB_URL" -v ON_ERROR_STOP=1 -q -c "SET client_min_messages TO warning" -f supabase/schema.sql
"$psql_bin" "$DB_URL" -v ON_ERROR_STOP=1 -q -c "SET client_min_messages TO warning" -f sql/001_paddle_schema.sql
"$psql_bin" "$DB_URL" -v ON_ERROR_STOP=1 -q -c "NOTIFY pgrst, 'reload schema'"
"$psql_bin" "$DB_URL" -v ON_ERROR_STOP=1 -q -c "INSERT INTO public.locations (location_id, access_token, refresh_token, token_expires_at, location_name, active) VALUES ('dev-local', 'dev-local-access', 'dev-local-refresh', 4102444800, 'Local dev', 1) ON CONFLICT (location_id) DO NOTHING;"
unset DB_URL
if ! curl -fsS http://127.0.0.1:3000/health >/dev/null 2>&1; then
  exec npm start
fi
